package com.apple.spark.operator;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonInclude;

@JsonInclude(JsonInclude.Include.NON_NULL)
@JsonIgnoreProperties(ignoreUnknown = true)
public class BatchSchedulerConfiguration {

    private String queue;

    private boolean gangSchedulingEnabled;

    private int reservationTimeoutInSeconds = 480;

    public String getQueue() {
        return queue;
    }

    public void setQueue(String queue) {
        this.queue = queue;
    }

    public boolean getGang() {
        return gangSchedulingEnabled;
    }

    public void setGang(boolean gangSchedulingEnabled) {
        this.gangSchedulingEnabled = gangSchedulingEnabled;
    }

    public int getReservationTimeoutInSeconds() {
        return reservationTimeoutInSeconds;
    }

    public void setReservationTimeoutInSeconds(int reservationTimeoutInSeconds) {
        this.reservationTimeoutInSeconds = reservationTimeoutInSeconds;
    }
}

